/* Public evidence index: authority, collection scope and editorial review stay separate. */
(function(root){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safe=u=>{try{const x=new URL(u);return x.protocol==='https:'&&x.hostname==='steamcommunity.com'&&!x.username&&!x.password&&!x.port&&/^\/app\/3079210\/discussions\/[01]\/\d+\/$/.test(x.pathname)&&[...x.searchParams.keys()].every(k=>['ctp','l'].includes(k))?x.href:'';}catch(_){return '';}};
 const forum=u=>{try{const x=new URL(u);return x.protocol==='https:'&&x.hostname==='steamcommunity.com'&&!x.username&&!x.password&&!x.port&&/^\/app\/3079210\/discussions\/[01]\/$/.test(x.pathname)&&!x.search&&!x.hash?x.href:'';}catch(_){return '';}};
 const channel=u=>{try{const x=new URL(u);return x.protocol==='https:'&&x.hostname==='www.youtube.com'&&!x.username&&!x.password&&!x.port&&/^\/@[A-Za-z0-9_.-]+\/?$/.test(x.pathname)&&!x.search&&!x.hash?x.href:'';}catch(_){return '';}};
 const time=v=>{const d=new Date(v);return v&&Number.isFinite(+d)?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not yet recorded';};
 const num=v=>Number.isSafeInteger(v)&&v>=0?v:0;
 const old=v=>!v||!Number.isFinite(Date.parse(v))||Date.now()-Date.parse(v)>30*3600000;
 const states={complete:'Fully scanned',partial:'Partially scanned',unavailable:'Could not scan',deferred:'Waiting for scan'};
 const change={baseline:'Historical baseline',new_reply:'New reply since monitoring began',edited:'Wording change detected',historical_discovery:'Older reply newly found'};
 const reasons={access_restricted:'Access restricted',deferred_access_restricted:'Deferred after access restriction',rate_limited:'Rate limited',deferred_rate_limited:'Deferred after rate limit',robots_restricted:'Automated access restricted',page_budget:'Page limit reached',run_budget:'Time/request budget reached',thread_changed_during_scan:'Thread changed during collection',listing_changed_during_scan:'Forum listing changed during collection',duplicate_listing_page:'Repeated or shifting listing page'};
 let data=null,filter='all',order='newest',scope='all';
 function unavailable(){const host=document.getElementById('staffResponses');if(host)host.innerHTML='<h2>Staff responses in monitored discussions</h2><p role="status">Discussion coverage could not be loaded. This does not mean there are no new staff responses.</p>';}
 function coverageRow(t){
  return '<div class="response-thread"><a href="'+esc(safe(t.url))+'" target="_blank" rel="noopener noreferrer">'+esc(t.title)+'</a><p>'+esc(states[t.state]||'Not checked')+(t.source_origin==='discovered'&&t.observed_this_run===false?' on a previous pass · Not rescanned this pass':'')+' · '+num(t.pages_checked)+' of '+(t.pages_expected==null?'unknown':num(t.pages_expected))+' pages; '+num(t.comments_seen)+' of '+(t.comments_expected==null?'unknown':num(t.comments_expected))+' comments checked.'+(t.failure_kind?' '+esc(reasons[t.failure_kind]||String(t.failure_kind).replaceAll('_',' '))+'.':'')+'</p><p class="response-small">Last complete scan: '+esc(time(t.last_complete_at))+'</p>'+(t.identities_pending||[]).map(a=>safe(a.evidence_url)?'<p class="response-small">Staff account awaiting verification: <a href="'+esc(safe(a.evidence_url))+'" target="_blank" rel="noopener noreferrer">Review source identity ↗</a></p>':'').join('')+'</div>';
 }
 function discoveryPanel(d){
  if(!d?.enabled)return '';
  const stale=old(d.last_attempt_at),listings=Array.isArray(d.listings)?d.listings:[];
  const checked=listings.reduce((n,l)=>n+num(l.pages_checked),0),planned=listings.reduce((n,l)=>n+num(l.pages_planned),0);
  return '<section id="discoveryCoverage"><h3>Finding discussions beyond our existing sources</h3><p class="response-coverage" data-complete="'+(d.state==='window_checked'&&!stale)+'">'+(stale?'Discovery check overdue. ':'')+checked+' of '+planned+' planned forum pages read. '+num(d.threads_complete_this_run)+' of '+num(d.threads_attempted_this_run)+' selected discussions fully scanned this pass.</p><p class="response-small">'+num(d.awaiting_first_complete_scan)+' candidates await their first complete scan; '+num(d.not_fully_scanned_this_run)+' candidates were not fully rescanned in this pass. '+num(d.zero_reply_leads_not_scanned)+' zero-reply leads are not scanned for replies.</p><p class="response-small">The first '+num(d.pages_per_forum)+' recently active pages of Report a Problem and General Discussions, plus a rotating follow-up list. Up to '+num(d.thread_limit_per_pass)+' discovered discussions per pass. This is a bounded search, not full Steam coverage. Original opening posts are outside this reply scan.</p><details class="response-details"><summary>Discovery coverage and backlog</summary>'+listings.map(l=>'<div class="response-thread">'+(forum(l.url)?'<a href="'+esc(forum(l.url))+'" target="_blank" rel="noopener noreferrer">'+esc(l.label)+'</a>':esc(l.label))+'<p>'+num(l.pages_checked)+' of '+num(l.pages_planned)+' planned pages · '+esc(l.state==='window_checked'?'Selected listing window checked':reasons[l.failure_kind]||l.failure_kind||'Incomplete')+'.</p></div>').join('')+(d.threads||[]).filter(t=>safe(t.url)).map(coverageRow).join('')+'<p class="response-small">Unscanned leads are candidates only; a title or last-poster name does not qualify as official evidence. New sources require relevance review before linking to the bug ledger. '+num(d.identities_pending)+' staff identities and '+num(d.content_reviews_pending)+' response previews await review.</p></details></section>';
 }
 function affiliatePanel(a){
  if(!a||!Array.isArray(a.channels))return '';
  return '<details id="affiliateCoverage" class="response-details"><summary>Affiliate sources · content monitoring not connected</summary><p>Selected public channel links are checked against the official War Correspondent directory. This does not scan their videos or comments, and partnership is not authority to speak for Team17.</p>'+a.channels.map(x=>'<div class="response-thread"><strong>'+esc(x.name)+'</strong> · '+(channel(x.channel_url)?'<a href="'+esc(channel(x.channel_url))+'" target="_blank" rel="noopener noreferrer">Open channel ↗</a>':'Channel link needs review')+'<p>'+esc(x.directory_status==='listed'?'Channel link found in the official directory':x.directory_status==='needs_review'?'Directory link requires review':'Directory could not be verified this pass')+'.</p><p class="response-small">Last directory verification: '+esc(time(x.last_directory_verified_at))+'. <strong>Replies not monitored.</strong></p></div>').join('')+'<a href="https://www.hellletloose.com/community" target="_blank" rel="noopener noreferrer">Official affiliate directory ↗</a></details>';
 }
 function render(value){
  if(value!==undefined)data=value;
  const host=document.getElementById('staffResponses');if(!host)return;
  if(!data||data.schema_version!==1||!Array.isArray(data.threads)){unavailable();return;}
  const stale=old(data.last_attempt_at);
  const complete=data.state==='complete'&&!stale&&num(data.threads_total)>0&&num(data.threads_complete)===num(data.threads_total);
  const discovery=data.discovery?.enabled?data.discovery:null;
  const found=discovery&&Array.isArray(discovery.threads)?discovery.threads:[];
  const tracked=data.threads.filter(t=>safe(t.url)).map(t=>({...t,source_origin:'tracked'}));
  const known=new Set(tracked.map(t=>safe(t.url)));
  const threads=[...tracked,...found.filter(t=>safe(t.url)&&!known.has(safe(t.url))).map(t=>({...t,source_origin:'discovered'}))];
  let entries=threads.filter(t=>scope==='all'||t.source_origin===scope).flatMap(t=>(t.replies||[]).filter(r=>safe(r.response_url)).map(r=>({...r,thread:t,activity_at:r.source_edited_at||r.published_at})));
  entries=entries.filter(r=>filter!=='changes'||['new_reply','edited'].includes(r.change_kind));
  entries=HLLVDates.sorted(entries,'activity_at',order);
  const cards=entries.map(r=>'<details class="response-entry" data-origin="'+r.thread.source_origin+'"><summary><time datetime="'+esc(r.activity_at)+'">'+(r.source_edited_at?'Edited ':'Posted ')+esc(time(r.activity_at))+'</time><strong>'+esc(r.thread.title)+'</strong><span>'+esc(r.author_label)+' · '+esc(r.source_category)+(r.thread.source_origin==='discovered'?' · Discovered source':'')+(r.content_review?.state==='needs_review'?' · Content needs review':'')+'</span></summary><div><p class="response-small">Originally posted '+esc(time(r.published_at))+' · '+esc(change[r.change_kind]||'Previously collected response')+(r.change_kind==='edited'?' · Change detected '+esc(time(r.last_changed_at)):'')+(r.source_edited_at?' · Source edit date '+esc(time(r.source_edited_at)):'')+'</p>'+(r.content_review?.state==='needs_review'?'<p class="response-review-hold"><strong>Preview withheld pending content review.</strong> '+esc(r.content_review.reason)+'</p>':r.excerpt?'<p>Response opening: “'+esc(r.excerpt)+'”</p>':'')+'<p class="response-small">'+(r.observed_this_run?'Staff identity and original response checked in this pass.':'Previously collected; not reverified in this pass. Absence is not proof of deletion.')+' Last seen: '+esc(time(r.last_seen_at))+'.</p><a href="'+esc(safe(r.response_url))+'" target="_blank" rel="noopener noreferrer">Read this staff response ↗</a><p class="response-small">'+(r.thread.source_origin==='discovered'?'New source discovery; not yet linked to a reviewed issue. Identity checks do not establish what this reply proves.':'Linked tracked issues: '+(r.thread.tracked_issue_ids||[]).filter(id=>/^HLLV-\d+$/.test(id)).map(id=>'<a href="#'+esc(id)+'">'+esc(id)+'</a>').join(' · ')+'. A thread link does not establish that this particular response addresses every linked issue.')+'</p></div></details>');
  const gaps=data.threads.filter(t=>t.state!=='complete');
  const allChecked=complete&&(!discovery||(discovery.state==='window_checked'&&!old(discovery.last_attempt_at)));
  host.innerHTML='<div class="feed-heading"><div><span class="section-kicker">Reply-level source monitoring</span><h2>Staff responses in monitored discussions</h2></div></div><p class="response-coverage" role="status" data-complete="'+complete+'">'+(stale?'Discussion check overdue. ':'')+num(data.threads_complete)+' of '+num(data.threads_total)+' existing issue-source discussions fully scanned in the last pass. '+(complete?'':'Coverage is incomplete or out of date. ')+'Attempted '+esc(time(data.last_attempt_at))+'.</p><p class="response-small">'+(discovery?'Existing issue sources and a bounded discovery pass—not every Steam discussion or affiliate channel.':'Existing tracked Steam threads only—not every Steam discussion or affiliate channel.')+' Attributable replies, not reviewed changes to bug status.</p><p class="response-small">Last complete pass for existing issue sources: '+esc(time(data.last_complete_at))+'. '+num(data.identities_pending)+' staff identities awaiting verification. '+num(data.content_reviews_pending)+' responses flagged for content review.</p><div class="response-tools"><label>Show <select id="responseFilter"><option value="all" '+(filter==='all'?'selected':'')+'>All collected responses</option><option value="changes" '+(filter==='changes'?'selected':'')+'>New or edited since monitoring began</option></select></label>'+(discovery?'<label>Sources <select id="responseScope"><option value="all" '+(scope==='all'?'selected':'')+'>All monitored sources</option><option value="tracked" '+(scope==='tracked'?'selected':'')+'>Existing issue sources</option><option value="discovered" '+(scope==='discovered'?'selected':'')+'>Discovered discussions</option></select></label>':'')+'<label>Date order <select id="responseOrder"><option value="newest" '+(order==='newest'?'selected':'')+'>Newest first</option><option value="oldest" '+(order==='oldest'?'selected':'')+'>Oldest first</option></select></label></div><div id="staffResponseList">'+(cards.length?cards.slice(0,3).join('')+(cards.length>3?'<details class="feed-more"><summary>More staff responses ('+(cards.length-3)+')</summary>'+cards.slice(3).join('')+'</details>':''):'<p>'+(filter==='changes'?'No new or edited qualifying response has been recorded since this monitor began. Older baseline responses remain under All collected responses.':'No verified staff responses have been collected for this scope yet.')+(allChecked?'':' Incomplete coverage prevents an all-clear conclusion.')+'</p>')+'</div><details class="response-details"><summary>Coverage by existing issue-source discussion'+(gaps.length?' · '+gaps.length+' incomplete':'')+'</summary>'+tracked.map(coverageRow).join('')+'<p class="response-small">Older replies found during setup are a historical baseline, not today’s news. New identities need review; names and quoted player text do not establish staff authority. No source scan changes Member/Moderator permissions.</p></details>'+discoveryPanel(discovery)+affiliatePanel(data.affiliate_monitor);
  for(const [id,set] of [['responseFilter',v=>filter=v],['responseOrder',v=>order=v],['responseScope',v=>scope=v]]){
   const el=host.querySelector('#'+id);if(el)el.onchange=e=>{set(e.target.value);render();host.querySelector('#'+id)?.focus({preventScroll:true});};
  }
 }
 root.HLLVResponses=Object.freeze({render,unavailable});
})(globalThis);
